import asyncio
from fastmcp import Server

async def main():
    server = Server("config-server")

    @server.resource("data://config")
    def get_config() -> dict:
        """Returns a static configuration dictionary."""
        return {
            "app_name": "ConfigServer",
            "version": "1.0.0",
            "environment": "production",
            "debug": False,
            "features": {
                "auth": True,
                "logging": True,
                "caching": True
            }
        }

    async with server:
        await server.run_stdio()

if __name__ == "__main__":
    asyncio.run(main())
